	"github.com/jackc/pgx/v5/pgxpool"
)

func NewPool(ctx context.Context, cfg PostgresConfig) (*pgxpool.Pool, error) {
	cfg, err := cfg.withDefaults()
	if err != nil {
		return nil, err
	}
	poolConfig, err := pgxpool.ParseConfig(cfg.URL)
	if err != nil {
		return nil, fmt.Errorf("postgres: invalid connection configuration: %w", sanitizeError(err))
	}
	poolConfig.MaxConns = cfg.MaxConns
	poolConfig.MinConns = cfg.MinConns
	poolConfig.MaxConnLifetime = cfg.ConnMaxLifetime
	poolConfig.ConnConfig.ConnectTimeout = cfg.ConnectTimeout
	if cfg.SearchPath != "" {
		poolConfig.ConnConfig.RuntimeParams["search_path"] = cfg.SearchPath
	}
	pool, err := pgxpool.NewWithConfig(ctx, poolConfig)
	if err != nil {
		return nil, fmt.Errorf("postgres: create pool: %w", sanitizeError(err))
	}
	if err := pool.Ping(ctx); err != nil {
		pool.Close()
		return nil, fmt.Errorf("postgres: ping: %w", sanitizeError(err))
	}
	return pool, nil
}

func sanitizeError(err error) error {
	if err == nil {
		return nil
	}
	// pgx may include connection details in parse errors. Keep the public
	// error suitable for logs; the underlying cause remains available to tests
	// through its category, not through credentials or DSN text.
	return fmt.Errorf("%s", redactConnectionText(err.Error()))
}

func redactConnectionText(message string) string {
	for _, prefix := range []string{"postgres://", "postgresql://"} {
		for {
			start := indexOf(message, prefix)
			if start < 0 {
				break
			}
			end := start
			for end < len(message) && message[end] != ' ' && message[end] != '\n' {
				end++
			}
			message = message[:start] + "[REDACTED-DSN]" + message[end:]
		}
	}
	return message
}

func indexOf(value, needle string) int {
	for i := 0; i+len(needle) <= len(value); i++ {
		if value[i:i+len(needle)] == needle {
			return i
		}
	}
	return -1
}

const claimScript = `local k=KEYS[1]; local seq=KEYS[2]; local owner=ARGV[1]; local ttl=tonumber(ARGV[2]); local now=redis.call('TIME')[1]; local v=redis.call('HGETALL',k); local h={}; for i=1,#v,2 do h[v[i]]=v[i+1] end; if h.status=='completed' then return {3,h.owner or '',h.attempt or '0',h.fence or '0',h.response or '',h.claimed or '0',h.expires or '0'} end; if h.owner and h.expires and tonumber(h.expires)>tonumber(now) then return {2,h.owner,h.attempt,h.fence,h.response or '',h.claimed,h.expires} end; local attempt=tonumber(h.attempt or '0')+1; local fence=redis.call('INCR',seq); local exp=tonumber(now)+ttl; redis.call('HSET',k,'status','acquired','owner',owner,'attempt',attempt,'fence',fence,'claimed',now,'expires',exp); redis.call('EXPIRE',k,ttl); return {1,owner,attempt,fence,'',now,exp}`
const claimWriteScript = `local k=KEYS[1]; local owner=ARGV[1]; local fence=ARGV[2]; local status=ARGV[3]; local response=ARGV[4]; local now=redis.call('TIME')[1]; local cur=redis.call('HMGET',k,'owner','fence','expires'); if cur[1]~=owner or cur[2]~=fence or not cur[3] or tonumber(cur[3])<=tonumber(now) then return 0 end; redis.call('HSET',k,'status',status,'response',response); return 1`

func (b *Backend) Claim(ctx context.Context, tc tenant.TenantContext, id string, ttl time.Duration) (storage.Claim, error) {
	if err := validateContext(ctx, tc, "claim"); err != nil {
		return storage.Claim{}, err
	}
	if id == "" {
		return storage.Claim{}, fmt.Errorf("%w: message id", ErrInvalidKey)
	}
	if ttl <= 0 {
		ttl = b.claimTTL
	}
	k, e := dedupKey(b.prefix, tc.TenantID, tc.Channel, tc.BindingID, id)
	if e != nil {
		return storage.Claim{}, e
	}
	seq, _ := key(b.prefix, "fence", "claim", tc.TenantID, tc.Channel, tc.BindingID, id)
	r, err := b.client.Eval(ctx, claimScript, []string{k, seq}, "claim", int(ttl.Seconds())).Result()
	if err != nil {
		return storage.Claim{}, mapRedisErr(err)
	}
	a, ok := r.([]interface{})
	if !ok || len(a) < 7 {
		return storage.Claim{}, fmt.Errorf("%w: claim result", ErrRedisUnavailable)
	}
	code, _ := resultInt(a[0])
	attempt, _ := strconv.Atoi(fmt.Sprint(a[2]))
	fence, _ := strconv.ParseUint(fmt.Sprint(a[3]), 10, 64)
	status := storage.ClaimInFlight
	if code == 1 {
		status = storage.ClaimAcquired
	}
	if code == 3 {
		status = storage.ClaimCompleted
	}
	claimed, _ := strconv.ParseInt(fmt.Sprint(a[5]), 10, 64)
	exp, _ := strconv.ParseInt(fmt.Sprint(a[6]), 10, 64)
	return storage.Claim{Key: storage.DedupKey{TenantID: tc.TenantID, Channel: tc.Channel, BindingID: tc.BindingID, ExternalMessageID: id}, Status: status, OwnerID: fmt.Sprint(a[1]), Attempt: attempt, FenceToken: fence, ResponseRef: fmt.Sprint(a[4]), ClaimedAt: time.Unix(claimed, 0).UTC(), ExpiresAt: time.Unix(exp, 0).UTC()}, nil
}
func (b *Backend) Complete(ctx context.Context, tc tenant.TenantContext, k storage.DedupKey, response string, fence uint64) error {
	return b.writeClaim(ctx, tc, k, "completed", response, fence)
}
func (b *Backend) Fail(ctx context.Context, tc tenant.TenantContext, k storage.DedupKey, fence uint64, retryable bool) error {
	status := "completed"
	if retryable {
		status = "acquired"
	}
	return b.writeClaim(ctx, tc, k, status, "", fence)
}
func (b *Backend) writeClaim(ctx context.Context, tc tenant.TenantContext, k storage.DedupKey, status, response string, fence uint64) error {
	if err := validateContext(ctx, tc, "claim"); err != nil {
		return err
	}
	key, _ := dedupKey(b.prefix, k.TenantID, k.Channel, k.BindingID, k.ExternalMessageID)
	r, err := b.client.Eval(ctx, claimWriteScript, []string{key}, "claim", strconv.FormatUint(fence, 10), status, response).Int()
	if err != nil {
		return mapRedisErr(err)
	}
	if r != 1 {
		return ErrFenceRejected
	}
	return nil
}

