package postgres

import (
	"context"
	"fmt"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
	"github.com/liuzengh/trpc-agent-service/trpcservice/storage"
	"github.com/liuzengh/trpc-agent-service/trpcservice/tenant"
)

type CoordinationStore struct { pool *pgxpool.Pool; epoch storage.Epoch }

func NewCoordinationStore(pool *pgxpool.Pool) (*CoordinationStore, error) {
	if pool == nil { return nil, fmt.Errorf("postgres: pool is required") }
	return &CoordinationStore{pool: pool, epoch: 1}, nil
}

func (s *CoordinationStore) Claim(ctx context.Context, tc tenant.TenantContext, key storage.DedupKey, ttl time.Duration, owner string) (storage.Claim, error) {
	if err := ctx.Err(); err != nil { return storage.Claim{}, err }
	if err := storage.ValidateDedupKey(key); err != nil || key.TenantID != tc.TenantID { if err != nil { return storage.Claim{}, err }; return storage.Claim{}, storage.ErrTenantMismatch }
	if owner == "" || ttl <= 0 { return storage.Claim{}, storage.ErrInvalidArgument }
	tx, err := s.pool.Begin(ctx); if err != nil { return storage.Claim{}, err }; defer tx.Rollback(ctx)
	_, err = tx.Exec(ctx, `SET LOCAL lock_timeout = '5s'; SET LOCAL statement_timeout = '15s'`); if err != nil { return storage.Claim{}, err }
	now := time.Now().UTC(); expiry := now.Add(ttl)
	_, err = tx.Exec(ctx, `INSERT INTO message_dedup (tenant_id, channel, binding_id, external_message_id, status, owner_id, attempt, fence_token, claimed_at, expires_at) VALUES ($1,$2,$3,$4,'acquired',$5,1,1,$6,$7) ON CONFLICT DO NOTHING`, key.TenantID,key.Channel,key.BindingID,key.ExternalMessageID,owner,now,expiry)
	if err != nil { return storage.Claim{}, err }
	var c storage.Claim
	var status string
	err = tx.QueryRow(ctx, `SELECT status, owner_id, attempt, fence_token, response_ref, claimed_at, expires_at FROM message_dedup WHERE tenant_id=$1 AND channel=$2 AND binding_id=$3 AND external_message_id=$4 FOR UPDATE`, key.TenantID,key.Channel,key.BindingID,key.ExternalMessageID).Scan(&status,&c.OwnerID,&c.Attempt,&c.FenceToken,&c.ResponseRef,&c.ClaimedAt,&c.ExpiresAt)
	if err != nil { if err == pgx.ErrNoRows { return storage.Claim{}, storage.ErrNotFound }; return storage.Claim{}, err }
	c.Key=key; c.Backend=storage.BackendPostgres; c.Epoch=s.epoch; c.Status=storage.ClaimStatus(status)
	if c.Status != storage.ClaimCompleted && c.ExpiresAt.Before(now) && c.OwnerID != owner {
		c.Attempt++ ; c.FenceToken++ ; c.OwnerID=owner; c.ClaimedAt=now; c.ExpiresAt=expiry; c.Status=storage.ClaimAcquired
		if _, err=tx.Exec(ctx, `UPDATE message_dedup SET status='acquired', owner_id=$5, attempt=$6, fence_token=$7, claimed_at=$8, expires_at=$9, updated_at=now() WHERE tenant_id=$1 AND channel=$2 AND binding_id=$3 AND external_message_id=$4`,key.TenantID,key.Channel,key.BindingID,key.ExternalMessageID,owner,c.Attempt,c.FenceToken,now,expiry); err != nil { return storage.Claim{}, err }
	}
	if err=tx.Commit(ctx); err != nil { return storage.Claim{}, err }; return c,nil
}

func (s *CoordinationStore) Complete(ctx context.Context, tc tenant.TenantContext, key storage.DedupKey, owner, response string, g storage.OperationGuard) error {
	if g.Backend != storage.BackendPostgres || g.OwnerID != owner || g.Epoch != s.epoch { return storage.ErrFenceRejected }
	return s.write(ctx, tc, key, owner, g.FenceToken, response, "completed")
}
func (s *CoordinationStore) Fail(ctx context.Context, tc tenant.TenantContext, key storage.DedupKey, owner string, g storage.OperationGuard, retryable bool) error { status:="completed"; if retryable { status="acquired" }; return s.write(ctx,tc,key,owner,g.FenceToken,"",status) }
func (s *CoordinationStore) write(ctx context.Context, tc tenant.TenantContext, key storage.DedupKey, owner string, fence uint64, response,status string) error { r,e:=s.pool.Exec(ctx,`UPDATE message_dedup SET status=$5,response_ref=NULLIF($6,''),updated_at=now() WHERE tenant_id=$1 AND channel=$2 AND binding_id=$3 AND external_message_id=$4 AND owner_id=$7 AND fence_token=$8 AND expires_at>now()`,key.TenantID,key.Channel,key.BindingID,key.ExternalMessageID,status,response,owner,fence); if e!=nil{return e}; if r.RowsAffected()!=1{return storage.ErrFenceRejected}; return nil }

var _ storage.ClaimStore = (*CoordinationStore)(nil)

