 l.TenantID=tc.TenantID;l.SessionID=resource;l.ResourceID=resource;l.Backend=storage.BackendPostgres;l.Epoch=s.epoch;if e=tx.Commit(ctx);e!=nil{return storage.Lease{},e};return l,nil
}
func(s *CoordinationStore) Renew(ctx context.Context,tc tenant.TenantContext,l storage.Lease,ttl time.Duration)(storage.Lease,error){if l.Backend!=storage.BackendPostgres||l.Epoch!=s.epoch{return l,storage.ErrEpochRejected};exp:=time.Now().UTC().Add(ttl);r,e:=s.pool.Exec(ctx,`UPDATE session_lease SET leased_until=$5,updated_at=now() WHERE tenant_id=$1 AND session_id=$2 AND owner_id=$3 AND fencing_token=$4 AND leased_until>now()`,tc.TenantID,l.SessionID,l.OwnerID,l.FenceToken,exp);if e!=nil{return l,e};if r.RowsAffected()!=1{return l,storage.ErrLeaseLost};l.ExpiresAt=exp;return l,nil}
func(s *CoordinationStore) Release(ctx context.Context,tc tenant.TenantContext,l storage.Lease)error{r,e:=s.pool.Exec(ctx,`DELETE FROM session_lease WHERE tenant_id=$1 AND session_id=$2 AND owner_id=$3 AND fencing_token=$4`,tc.TenantID,l.SessionID,l.OwnerID,l.FenceToken);if e!=nil{return e};if r.RowsAffected()!=1{return storage.ErrFenceRejected};return nil}
func(s *CoordinationStore) Validate(ctx context.Context,tc tenant.TenantContext,l storage.Lease)error{var exp time.Time;e:=s.pool.QueryRow(ctx,`SELECT leased_until FROM session_lease WHERE tenant_id=$1 AND session_id=$2 AND owner_id=$3 AND fencing_token=$4`,tc.TenantID,l.SessionID,l.OwnerID,l.FenceToken).Scan(&exp);if e==pgx.ErrNoRows{return storage.ErrLeaseLost};if e!=nil{return e};if !exp.After(time.Now().UTC()){return storage.ErrLeaseLost};return nil}
var _ storage.LeaseStore=(*CoordinationStore)(nil)

