package coordination

import (
 "context"
 "sync"
 "time"
 "github.com/liuzengh/trpc-agent-service/trpcservice/storage"
 "github.com/liuzengh/trpc-agent-service/trpcservice/tenant"
)

type State string
const ( RedisActive State="redis_active"; Quarantine State="quarantine"; PostgresActive State="postgres_active" )
type Backend interface { Claim(context.Context,tenant.TenantContext,storage.DedupKey,time.Duration,string)(storage.Claim,error) }
type FailoverStore struct { mu sync.Mutex; redis,postgres Backend; state State; until time.Time }
func NewFailoverStore(r,p Backend) *FailoverStore{return &FailoverStore{redis:r,postgres:p,state:RedisActive}}
func (f *FailoverStore) Claim(ctx context.Context,tc tenant.TenantContext,k storage.DedupKey,ttl time.Duration,owner string)(storage.Claim,error){f.mu.Lock();defer f.mu.Unlock();if f.state==Quarantine&&time.Now().Before(f.until){return storage.Claim{},storage.ErrBackendUnavailable};var b Backend=f.redis;if f.state==PostgresActive{b=f.postgres};c,e:=b.Claim(ctx,tc,k,ttl,owner);if e!=nil&&f.state==RedisActive{f.state=Quarantine;f.until=time.Now().Add(ttl);return storage.Claim{},storage.ErrOperationAmbiguous};return c,e}
